"  const handleToggleSelectReceipt = (e, orderId) => {
    e.stopPropagation();
    const isChecking = !selectedReceiptIds.includes(orderId);
    setSelectedReceiptIds(prev => 
      isChecking 
        ? [...prev, orderId] 
        : prev.filter(id => id !== orderId)
    );
    if (isChecking) {
      const order = recentOrders.find(o => o.id === orderId);
      if (order) {
        setSelectedReceipt(order);
      }
    } else {
      if (selectedReceipt?.id === orderId) {
        setSelectedReceipt(null);
      }
    }
  };

  const handleToggleSelectAll = () => {
    const isAllSelected = paginatedOrders.length > 0 && paginatedOrders.every(o => selectedReceiptIds.includes(o.id));
    if (isAllSelected) {
      const visibleIds = new Set(paginatedOrders.map(o => o.id));
      setSelectedReceiptIds(prev => prev.filter(id => !visibleIds.has(id)));
      if (selectedReceipt && visibleIds.has(selectedReceipt.id)) {
        setSelectedReceipt(null);
      }
    } else {
      const visibleIds = paginatedOrders.map(o => o.id);
      setSelectedReceiptIds(prev => {
        const next = new Set([...prev, ...visibleIds]);
        return Array.from(next);
      });
      if (paginatedOrders.length > 0) {
        setSelectedReceipt(paginatedOrders[0]);
      }
    }
  };"

